const setJobWanted = `-- name: SetJobWanted :exec
UPDATE job SET wanted_until = CASE
    WHEN CAST(?1 AS INTEGER) = 1 THEN
      CASE WHEN wanted_until IS NULL THEN NULL ELSE CAST(?2 AS INTEGER) END
    ELSE MAX(COALESCE(wanted_until, 0), CAST(?2 AS INTEGER))
  END
WHERE kind = ?3 AND state IN ('queued', 'running', 'assigned')
  AND item_id IS ?4 AND stream_id IS ?5
  AND fetched_subtitle_id IS ?6 AND file_id IS ?7
  AND scan_id IS ?8 AND scan_batch_id IS ?9
  AND chunk_store_id IS ?10
`

type SetJobWantedParams struct {
	IsRelease         int64
	Until             int64
	Kind              string
	ItemID            *int64
	StreamID          *int64
	FetchedSubtitleID *int64
	FileID            *int64
	ScanID            *int64
	ScanBatchID       *int64
	ChunkStoreID      *int64
}

// When a person stops waiting for an open job of a kind on a target. Kept wanted (is_release 0),
// until, unless a later play said later (D240 section 6). Released (is_release 1), as by one who left
// the page that asked for it, until, a moment past, if anyone waited, so the next demotion gives it
// background priority (D258 section 2); a player still watching asks again, and keeps it wanted.
func (q *Queries) SetJobWanted(ctx context.Context, arg SetJobWantedParams) error {
	_, err := q.db.ExecContext(ctx, setJobWanted,
		arg.IsRelease,
		arg.Until,
		arg.Kind,
		arg.ItemID,
		arg.StreamID,
		arg.FetchedSubtitleID,
		arg.FileID,
		arg.ScanID,
		arg.ScanBatchID,
		arg.ChunkStoreID,
	)
	return err
}

const startJob = `-- name: StartJob :one
UPDATE job SET state = 'running', attempt_count = attempt_count + 1
WHERE id = ?1 AND state = 'queued'
RETURNING id, kind, item_id, stream_id, fetched_subtitle_id, file_id, scan_id, scan_batch_id, chunk_store_id, args_json, priority, state, destination,
          runnable_at, is_snoozed, attempt_count, last_attempt_tool_failed, progress_fraction, reason, last_failure,
          created_at, finished_at, assigned_until, wanted_until
`

// A claim: the job runs, and its attempt is counted.
func (q *Queries) StartJob(ctx context.Context, id int64) (Job, error) {
	row := q.db.QueryRowContext(ctx, startJob, id)
	var i Job
	err := row.Scan(
		&i.ID,
		&i.Kind,
		&i.ItemID,
		&i.StreamID,
		&i.FetchedSubtitleID,
		&i.FileID,
		&i.ScanID,
		&i.ScanBatchID,
		&i.ChunkStoreID,
		&i.ArgsJSON,
		&i.Priority,
		&i.State,
		&i.Destination,
		&i.RunnableAt,
		&i.IsSnoozed,
		&i.AttemptCount,
		&i.LastAttemptToolFailed,
		&i.ProgressFraction,
		&i.Reason,
		&i.LastFailure,
		&i.CreatedAt,
		&i.FinishedAt,
		&i.AssignedUntil,
		&i.WantedUntil,
	)
	return i, err
}

const takeAssignedJob = `-- name: TakeAssignedJob :one
UPDATE job SET state = 'running'
WHERE id = ?1 AND state = 'assigned'
RETURNING id, kind, item_id, stream_id, fetched_subtitle_id, file_id, scan_id, scan_batch_id, chunk_store_id, args_json, priority, state, destination,
          runnable_at, is_snoozed, attempt_count, last_attempt_tool_failed, progress_fraction, reason, last_failure,
          created_at, finished_at, assigned_until, wanted_until
`

